def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    ratio = v1 / v2
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "due_after_5_years": v1,
            "total_scheduled_maturities": v2,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
